// 좋음: 부르는 쪽이 알아야 할 것이 적다
interface Storage {
  save(note: Note): Promise<void>;
  load(id: string): Promise<Note | null>;
}

// 나쁨: 내부 사정이 새어 나온다
interface Storage {
  openConnection(): Promise<Conn>;
  beginTx(c: Conn): Promise<Tx>;
  insertRow(tx: Tx, table: string, row: object): Promise<void>;
}
